"""miner_2 batch-3 factor exploration - NOVEL families not covered in earlier batches.

Families:
  A. Relative strength vs cross-asset peers + trend acceleration / consistency
  B. Risk-adjusted return (Sharpe, Sortino), return autocorrelation (trend persistence)
  C. Intraday vs overnight return split (uses open) - novel for this universe
  D. Garman-Klass / Parkinson intraday-range volatility and vol-ratio (uses high/low)
  E. Cross-asset conditional betas anchored on TRADABLE assets (SPX, XAU, BTC, US10Y)
  F. Volume-weighted momentum (amihud trend), OBV slope

Validation window: 2020-01-01 .. 2026-07-15 (warm-up, no lookahead).
Admission gates (15-asset universe, horizon 10): |IC| >= 0.0070, |ICIR| >= 0.0840.
Per-asset OWN calendar computation (BTC/ETH 7d/week vs 5d/week equities).
"""
import numpy as np
import pandas as pd
from scipy.stats import spearmanr
from alphacrafter.sim.utils import get_stock_daily_data

WL = ['000300.SH', 'SPX', 'HSI', 'N225', 'SX5E', '000688.SH', 'SOX', 'NDX',
      'XAU', 'COPPER', 'WTI', 'BTC', 'ETH', 'US10Y', 'CN10Y']
END = pd.Timestamp('2026-07-15')
MIN_ASSETS = 8
HORIZON = 10


def load_asset(sym):
    df = get_stock_daily_data(symbol=sym, days=4000)
    if df is None:
        return None
    df = df.copy()
    df['date'] = pd.to_datetime(df['date'])
    df = df[df['date'] <= END].set_index('date')
    for c in ['open', 'high', 'low', 'close', 'volume']:
        if c in df.columns:
            df[c] = pd.to_numeric(df[c], errors='coerce')
    return df[df['close'].notna()]


frames = {s: load_asset(s) for s in WL}
print(f"assets loaded: {sum(1 for v in frames.values() if v is not None)}/{len(WL)}")

# macro signals (observation-only)
mac = {}
for m in ['VIX', 'DXY', 'USDJPY', 'EURUSD', 'USDCNY']:
    d = pd.read_csv(f"../persistent/index_data/{m}.csv")
    d['date'] = pd.to_datetime(d['date'])
    d = d[d['date'] <= END].set_index('date')
    d['close'] = pd.to_numeric(d['close'], errors='coerce')
    mac[m] = d['close'].dropna()
    mac[m + '_ret'] = mac[m].pct_change()

idx = pd.DatetimeIndex(sorted(set().union(*[f.index for f in frames.values() if f is not None])))
closes = pd.DataFrame({s: frames[s]['close'].reindex(idx) for s in WL if frames[s] is not None}, index=idx)
opens = pd.DataFrame({s: frames[s]['open'].reindex(idx) for s in WL if frames[s] is not None}, index=idx)
highs = pd.DataFrame({s: frames[s]['high'].reindex(idx) for s in WL if frames[s] is not None}, index=idx)
lows = pd.DataFrame({s: frames[s]['low'].reindex(idx) for s in WL if frames[s] is not None}, index=idx)
volume = pd.DataFrame({s: frames[s]['volume'].reindex(idx) for s in WL if frames[s] is not None}, index=idx)
rets = closes.pct_change()


def clean_panel(func):
    out = {}
    for a in WL:
        s = closes[a].dropna()
        if len(s) < 30:
            out[a] = pd.Series(np.nan, index=idx)
            continue
        try:
            r = func(s)
            out[a] = r.reindex(idx)
        except Exception:
            out[a] = pd.Series(np.nan, index=idx)
    return pd.DataFrame(out, index=idx)


def clean_rets(func):
    out = {}
    for a in WL:
        s = closes[a].dropna().pct_change()
        if len(s) < 30:
            out[a] = pd.Series(np.nan, index=idx)
            continue
        try:
            r = func(s)
            out[a] = r.reindex(idx)
        except Exception:
            out[a] = pd.Series(np.nan, index=idx)
    return pd.DataFrame(out, index=idx)


def fwd_panel(h):
    out = {}
    for a in WL:
        s = closes[a].dropna()
        r = s.shift(-h) / s - 1.0
        out[a] = r.reindex(idx)
    return pd.DataFrame(out, index=idx)


FWD = {h: fwd_panel(h) for h in (1, 2, 3, 5, 10, 20)}

C = {}

# ---------- A. relative strength & trend structure ----------
mom20 = clean_panel(lambda s: s / s.shift(20) - 1.0)
mom60 = clean_panel(lambda s: s / s.shift(60) - 1.0)
mom120 = clean_panel(lambda s: s / s.shift(120) - 1.0)
xs_mean20 = mom20.mean(axis=1)
xs_mean60 = mom60.mean(axis=1)
C['rel_mom_20d'] = mom20.sub(xs_mean20, axis=0)
C['rel_mom_60d'] = mom60.sub(xs_mean60, axis=0)
C['accel_60_20'] = clean_panel(lambda s: (s / s.shift(60) - 1.0) - (s / s.shift(20) - 1.0))
C['trend_consist_60'] = clean_rets(lambda r: (r > 0).rolling(60).mean() * 2.0 - 1.0)
C['updown_ratio_60'] = clean_rets(lambda r: (r.clip(lower=0).rolling(60).sum().abs())
                                  / (r.clip(upper=0).rolling(60).sum().abs() + 1e-9))

# ---------- B. risk-adjusted return & autocorrelation ----------
C['sharpe_60d'] = clean_rets(lambda r: r.rolling(60).mean() / r.rolling(60).std())
C['sortino_60d'] = clean_rets(lambda r: r.rolling(60).mean() / np.sqrt((r.clip(upper=0) ** 2).rolling(60).mean()))
C['autocorr_20d'] = clean_rets(lambda r: r.rolling(20).apply(lambda x: x.autocorr() if len(x) >= 8 and x.std() > 0 else np.nan, raw=False))
C['autocorr_60d'] = clean_rets(lambda r: r.rolling(60).apply(lambda x: x.autocorr() if len(x) >= 30 and x.std() > 0 else np.nan, raw=False))

# ---------- C. intraday / overnight split ----------
def intraday_ratio(win=20):
    out = {}
    for a in WL:
        s = closes[a].dropna()
        o = opens[a].reindex(s.index)
        d = pd.concat([s.pct_change().rename('r'), (s / o - 1.0).rename('intra'), (o / s.shift(1) - 1.0).rename('on')], axis=1)
        out[a] = (d['intra'].rolling(win).sum() / (d['intra'].abs().rolling(win).sum() + 1e-12)).reindex(idx)
    return pd.DataFrame(out, index=idx)

C['intraday_eff_20'] = intraday_ratio(20)  # signed efficiency of intraday moves
C['overnight_mom_20'] = clean_panel(lambda s: (opens[a].reindex(s.index) / s.shift(1) - 1.0).rolling(20).sum()
                                    if False else None)  # placeholder replaced below


def overnight_mom(win=20):
    out = {}
    for a in WL:
        s = closes[a].dropna()
        o = opens[a].reindex(s.index)
        on = o / s.shift(1) - 1.0
        out[a] = on.rolling(win).sum().reindex(idx)
    return pd.DataFrame(out, index=idx)


C['overnight_mom_20'] = overnight_mom(20)


def intraday_mom(win=20):
    out = {}
    for a in WL:
        s = closes[a].dropna()
        o = opens[a].reindex(s.index)
        intr = s / o - 1.0
        out[a] = intr.rolling(win).sum().reindex(idx)
    return pd.DataFrame(out, index=idx)


C['intraday_mom_20'] = intraday_mom(20)

# ---------- D. Garman-Klass / Parkinson vol ----------
def gk_vol(win=20):
    out = {}
    for a in WL:
        s = closes[a].dropna()
        h, l, o = highs[a].reindex(s.index), lows[a].reindex(s.index), opens[a].reindex(s.index)
        gk = 0.5 * np.log(h / l) ** 2 - (2 * np.log(2) - 1) * np.log(o / s.shift(1)) ** 2
        out[a] = np.sqrt(gk.rolling(win).mean().clip(lower=0)).reindex(idx)
    return pd.DataFrame(out, index=idx)


C['gk_vol_20'] = gk_vol(20)


def park_vol(win=20):
    out = {}
    for a in WL:
        s = closes[a].dropna()
        h, l = highs[a].reindex(s.index), lows[a].reindex(s.index)
        pk = (np.log(h / l) ** 2).rolling(win).mean() / (4 * np.log(2))
        out[a] = np.sqrt(pk.clip(lower=0)).reindex(idx)
    return pd.DataFrame(out, index=idx)


C['park_vol_20'] = park_vol(20)
C['gk_cc_vol_ratio_20'] = C['gk_vol_20'] / (rets.rolling(20).std() + 1e-12)
C['down_up_vol_ratio_20'] = clean_rets(lambda r: r.clip(upper=0).rolling(20).std() / (r.clip(lower=0).rolling(20).std() + 1e-12))

# ---------- E. conditional betas anchored on TRADABLE assets ----------
def cond_beta(anchor_ret, sign, win=60, cond_mom=20):
    out = {}
    for a in WL:
        s = closes[a].dropna()
        ar = anchor_ret.reindex(s.index).dropna()
        d = pd.concat([s.pct_change().rename('a'), ar.rename('c')], axis=1).dropna()
        if len(d) < 120:
            out[a] = pd.Series(np.nan, index=idx)
            continue
        beta = d['a'].rolling(win).cov(d['c']) / d['c'].rolling(win).var().replace(0, np.nan)
        anchor = closes[anchor_name].dropna() if False else None
        out[a] = (sign * beta * ar.rolling(cond_mom).mean() * cond_mom).reindex(idx)
    return pd.DataFrame(out, index=idx)


def cond_beta_series(anchor_sym, sign, win=60, cond_mom=20):
    """signal = sign * beta(asset, anchor) * anchor_momentum(cond_mom)"""
    anc = closes[anchor_sym].dropna()
    anc_ret = anc.pct_change()
    anc_mom = anc.pct_change().rolling(cond_mom).mean() * cond_mom
    out = {}
    for a in WL:
        s = closes[a].dropna()
        d = pd.concat([s.pct_change().rename('a'), anc_ret.rename('c')], axis=1).dropna()
        if len(d) < 120:
            out[a] = pd.Series(np.nan, index=idx)
            continue
        beta = d['a'].rolling(win).cov(d['c']) / d['c'].rolling(win).var().replace(0, np.nan)
        out[a] = (sign * beta * anc_mom.reindex(beta.index)).reindex(idx)
    return pd.DataFrame(out, index=idx)


C['eq_beta_spx_60x20'] = cond_beta_series('SPX', 1.0)          # risk-on sensitivity x SPX momentum
C['safehav_beta_xau_60x20'] = cond_beta_series('XAU', 1.0)     # gold beta x gold momentum
C['crypto_beta_btc_60x20'] = cond_beta_series('BTC', 1.0)      # crypto beta x BTC momentum
C['rate_beta_us10y_60x20'] = cond_beta_series('US10Y', -1.0)   # -yield beta x yield momentum
C['defensive_spx_60x20'] = cond_beta_series('SPX', -1.0)       # defensive: -beta x SPX momentum

# macro-conditioned (observation-only signals)
for m in ['VIX', 'DXY']:
    anc = mac[m]
    anc_ret = anc.pct_change()
    anc_mom = anc_ret.rolling(20).mean() * 20.0
    sign = 1.0 if m == 'VIX' else -1.0
    out = {}
    for a in WL:
        s = closes[a].dropna()
        d = pd.concat([s.pct_change().rename('a'), anc_ret.reindex(s.index).dropna().rename('c')], axis=1).dropna()
        if len(d) < 120:
            out[a] = pd.Series(np.nan, index=idx)
            continue
        beta = d['a'].rolling(60).cov(d['c']) / d['c'].rolling(60).var().replace(0, np.nan)
        out[a] = (sign * beta * anc_mom.reindex(beta.index)).reindex(idx)
    C[f'{m.lower()}_beta2_60x20'] = pd.DataFrame(out, index=idx)

# ---------- F. volume-weighted momentum / OBV ----------
def vw_mom(win=20):
    out = {}
    for a in WL:
        s = closes[a].dropna()
        v = volume[a].reindex(s.index).fillna(0.0)
        r = s.pct_change()
        out[a] = ((v * r).rolling(win).sum() / (v.rolling(win).sum() + 1e-9)).reindex(idx)
    return pd.DataFrame(out, index=idx)


C['vw_mom_20d'] = vw_mom(20)


def obv_slope(win=60):
    out = {}
    for a in WL:
        s = closes[a].dropna()
        v = volume[a].reindex(s.index).fillna(0.0)
        obv = (np.sign(s.diff()) * v).cumsum()
        slope = (obv - obv.rolling(win).mean()) / (obv.rolling(win).std() + 1e-12)
        out[a] = slope.reindex(idx)
    return pd.DataFrame(out, index=idx)


C['obv_z_60d'] = obv_slope(60)

# ---------- library signals (for correlation provenance) ----------
LIB = {}
LIB['mom_10d_skip5'] = clean_panel(lambda s: s.shift(5) / s.shift(15) - 1.0)
LIB['mom_120d_skip5'] = clean_panel(lambda s: s.shift(5) / s.shift(125) - 1.0)
LIB['vol_of_vol20x60'] = clean_rets(lambda r: r.rolling(20).std().rolling(60).std())
LIB['vix_beta_cond_60x20'] = cond_beta_series('SPX', 0.0)  # placeholder, not used
# real vix library signal
vix_anc = mac['VIX']
vix_ret = vix_anc.pct_change()
vix_mom = vix_ret.rolling(20).mean() * 20.0
vix_lib = {}
for a in WL:
    s = closes[a].dropna()
    d = pd.concat([s.pct_change().rename('a'), vix_ret.reindex(s.index).dropna().rename('c')], axis=1).dropna()
    if len(d) < 120:
        vix_lib[a] = pd.Series(np.nan, index=idx)
        continue
    beta = d['a'].rolling(60).cov(d['c']) / d['c'].rolling(60).var().replace(0, np.nan)
    vix_lib[a] = (-1.0 * beta * vix_mom.reindex(beta.index)).reindex(idx)
LIB['vix_beta_cond_60x20'] = pd.DataFrame(vix_lib, index=idx)


# ---------- IC machinery ----------
def ic_series(fp, h=HORIZON):
    fwd = FWD[h]
    out = {}
    for t in fp.index:
        if t.dayofweek >= 5:
            continue
        fv = fp.loc[t]
        fr = fwd.loc[t].reindex(fv.index)
        m = fv.notna() & fr.notna()
        if int(m.sum()) < MIN_ASSETS:
            continue
        ic, _ = spearmanr(fv[m], fr[m])
        if np.isfinite(ic):
            out[t] = ic
    return pd.Series(out)


def max_lib_corr(fp):
    best, best_key = 0.0, None
    for lid, lp in LIB.items():
        both = pd.concat([fp.stack().rename('c'), lp.stack().rename('l')], axis=1).dropna()
        if len(both) < 300:
            continue
        r = float(both['c'].corr(both['l']))
        if abs(r) > best:
            best, best_key = abs(r), lid
    return best, best_key


def analyze(name, fp):
    ic = ic_series(fp)
    if len(ic) < 200:
        return dict(name=name, n_ic=len(ic), note='insufficient IC dates')
    icir = ic.mean() / ic.std(ddof=1)
    hit = float((np.sign(ic) == np.sign(ic.mean())).mean())
    valid = fp.notna()
    cov_ad = float(valid.sum().sum() / (len(fp) * len(fp.columns)))
    wd = fp.index.dayofweek < 5
    cov_d8 = float(((valid.sum(axis=1) >= MIN_ASSETS) & wd).mean())
    ranks = fp.rank(axis=1)
    to = float((ranks - ranks.shift(10)).abs().mean().mean())
    rho, rkey = max_lib_corr(fp)
    decay = {}
    for h in (1, 2, 3, 5, 10, 20):
        s = ic_series(fp, h)
        if len(s) >= 100:
            decay[str(h)] = round(float(s.mean()), 4)
    return dict(name=name, ic=round(float(ic.mean()), 4), icir=round(float(icir), 4),
                hit=round(hit, 3), n_ic=len(ic), cov_ad=round(cov_ad, 3), cov_d8=round(cov_d8, 3),
                to=round(to, 3), rho=round(rho, 3), rkey=rkey, decay=decay)


results = []
for name, fp in C.items():
    res = analyze(name, fp)
